#include <stdio.h>
#include <ctype.h>
int main() {
    char s[1000]; if (scanf("%s", s) != 1) return 0;
    int i = 0;
    while (s[i]) {
        if (isalpha(s[i])) {
            char c = s[i++];
            int cnt = 0;
            while (isdigit(s[i])) cnt = cnt * 10 + (s[i++] - '0');
            for (int k = 0; k < cnt; k++) putchar(c);
        } else i++;
    }
    putchar('\n');
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <cctype>
using namespace std;
int main() {
    string s; if (cin >> s) {
        string res = "";
        size_t i = 0;
        while (i < s.length()) {
            if (isalpha(s[i])) {
                char c = s[i++];
                int cnt = 0;
                while (i < s.length() && isdigit(s[i])) cnt = cnt * 10 + (s[i++] - '0');
                res.append(cnt, c);
            } else i++;
        }
        cout << res << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < s.length()) {
                if (Character.isLetter(s.charAt(i))) {
                    char c = s.charAt(i++);
                    int cnt = 0;
                    while (i < s.length() && Character.isDigit(s.charAt(i))) cnt = cnt * 10 + (s.charAt(i++) - '0');
                    for (int k = 0; k < cnt; k++) sb.append(c);
                } else i++;
            }
            System.out.println(sb.toString());
        }
    }
}

