    parts = re.findall(r"([a-zA-Z])(\d+)", s)
    print("".join(ch * int(cnt) for ch, cnt in parts))
if __name__ == "__main__": main()

code.JavaScript:
const fs = require("fs");
function main() {
    const s = fs.readFileSync(0, "utf-8").trim();
    let res = "";
    const re = /([a-zA-Z])(\d+)/g;
    let match;
    while ((match = re.exec(s)) !== null) {
        res += match[1].repeat(parseInt(match[2], 10));
    }
    console.log(res);
}
main();

